S x(name text,reading text,slug text,aliases text[],summary text,divinity text)), deity_upsert AS (INSERT INTO public.deities(name,reading,slug,aliases,summary,divinity,is_published) SELECT x.name,x.reading,x.slug,x.aliases,x.summary,x.divinity,true FROM deity_data x WHERE NOT EXISTS (SELECT 1 FROM public.deities old WHERE old.slug=x.slug OR old.name=x.name) ON CONFLICT (slug) DO UPDATE SET is_published=true RETURNING id) SELECT jsonb_build_object('new_deities',(SELECT count(*) FROM deity_upsert)) AS inserted;